/** Exported so this module is a Fast Refresh boundary, as the prototype's is. */
export function Root() {
  useReportBackground()
  const Frame = frame['./index.tsx']?.default
  const live = useLiveProps(idAfter(window.location.pathname, '/frames/'))
  const path = typeof window !== 'undefined' ? window.location.pathname.replace(/(.)\/$/, '$1') : ''
  // Keep a reading link from any ?t= URL on this device (one link per reader).
  useState(() => (path !== '/admin' ? captureReaderToken() : null))
  // Direct-reader route: /research/<slug> renders the article view.
  const [readerOpen, setReaderOpen] = useState(() => path in READER_ROUTES)
  if (path === '/admin') {
    return <AdminDashboard />
  }
  const authorSlug = path.startsWith('/research/authors/') ? path.slice('/research/authors/'.length).replace(/\/$/, '') : ''
  if (authorSlug && AUTHORS[authorSlug]) {
    return <AuthorProfile author={AUTHORS[authorSlug]} />
  }
  if (readerOpen && READER_ROUTES[path]) {
    return (
      <ArticleReader
        meta={READER_ROUTES[path]}
        onBack={() => {
          window.history.pushState({}, '', '/')
          setReaderOpen(false)
        }}
      />
    )
  }
  // /research (the link a reader gets when approved without a piece) opens
  // the home with the research list showing.
  if (path === '/research' && Frame) return <Frame {...live} state="research" />
  return Frame ? <Frame {...live} /> : <Blank />
}

/**
 * The props the canvas is showing while one of its controls changes, or the
 * ones a canvas placement draws it with, which are asked for on every start.
 * Drawn at `/`, the frame has no id to be told by, and takes any frame's.
 */
function useLiveProps(id: string | null): Props {
  const [live, setLive] = useState<Props>({})
  useEffect(() => {
    const onMessage = (event: MessageEvent) => {
      const data = event.data
      if (!data || data.type !== 'mp:frame-props') return
      if (id !== null && data.frameId !== id) return
      setLive(data.props && typeof data.props === 'object' ? data.props : {})
    }
    window.addEventListener('message', onMessage)
    if (embedded) {
      window.parent.postMessage({ type: 'mp:frame-props-request', frameId: id }, '*')
    }
    return () => window.removeEventListener('message', onMessage)
  }, [id])
  return live
}

function useReportBackground() {
  useEffect(() => {
    if (!embedded) return
    let last = ''
    const report = () => {
      let node: Element | null = document.elementFromPoint(2, 2)
      let color = ''
      while (node) {
        const value = getComputedStyle(node).backgroundColor
        if (value && value !== 'transparent' && !/rgba\(.*,\s*0\)$/.test(value)) {
          color = value
          break
        }
        node = node.parentElement
      }
      color = color || '#ffffff'
      if (color === last) return
      last = color
      window.parent.postMessage({ type: 'mp:frames-background', color }, '*')
    }
    report()
    const timer = window.setInterval(report, 1000)
    return () => window.clearInterval(timer)
  }, [])
}

function idAfter(path: string, prefix: string): string | null {
  const at = path.lastIndexOf(prefix)
  if (at === -1) return null
  const id = path.slice(at + prefix.length).split('/')[0]
  if (!id) return null
  try {
    return decodeURIComponent(id)
  } catch {
    return id
  }
}

/** A screen with nothing to draw yet. A blank sheet, not an error. */
function Blank() {
  return <div data-mp-placeholder className="min-h-full w-full bg-slate-50" />
}

const rootEl = document.getElementById('root')
if (rootEl && !hot?.data.root) {
  const root = ReactDOM.createRoot(rootEl)
  root.render(<Root />)
  if (hot) hot.data.root = root
}
